typedef enum { SEQ_SAME, SEQ_NEWER, SEQ_OLDER, SEQ_AMBIGUOUS } seq_rel_t;

seq_rel_t seq_compare(uint8_t seq, uint8_t newest)
{
  uint8_t d = (uint8_t)(seq - newest);
  if (d == 0)   { return SEQ_SAME; }
  if (d < 128)  { return SEQ_NEWER; }
  if (d == 128) { return SEQ_AMBIGUOUS; }
  return SEQ_OLDER;
}

int wrap_mod(int to, int from, int y)        /* y > 0 */
{
  return ((to - from) % y + y) % y;
}
