uint32_t range_and(uint32_t left, uint32_t right)
{
  unsigned shift = 0;
  while (left != right) { left >>= 1; right >>= 1; shift++; }
  return left << shift;
}
/* 5..7:  101 110 111 -> shift right until equal (both 1 after 2 shifts) -> 1 << 2 = 4 */

